26	/**
27	 * SMTP config comes from the Setting table (admin-editable) with env fallback.
28	 * Keys: smtp_host, smtp_port, smtp_user, smtp_pass, smtp_from, smtp_secure.
29	 * If nothing is configured, falls back to a local sendmail/Postfix relay on :25.
30	 */
31	/**
32	 * The stored SMTP password, decrypted — tolerating a LEGACY plaintext row.
33	 *
34	 * `smtp_pass` is now written through `encryptSecret` (iv:tag:ciphertext), but a
35	 * value saved before that change is bare plaintext. `decryptSecret` returns null
36	 * on a value that is not in the encrypted shape, so a null result means "this was
37	 * never encrypted" — fall back to the raw stored value. Once an operator re-saves
38	 * the SMTP settings, the row is encrypted and this fallback stops being taken.
39	 */
40	function smtpPassPlain(stored: string | undefined): string {
41	  if (!stored) return "";
42	  const dec = decryptSecret(stored);
43	  return dec ?? stored;
44	}
45	
46	async function loadSmtp() {
47	  const rows = await db.setting.findMany({
48	    where: { key: { in: ["smtp_host", "smtp_port", "smtp_user", "smtp_pass", "smtp_from", "smtp_secure"] } },
49	  });
50	  const s = Object.fromEntries(rows.map((r) => [r.key, r.value]));
51	  const host = s.smtp_host || process.env.SMTP_HOST || "";
52	  const from = s.smtp_from || process.env.SMTP_FROM || `Nxeon <no-reply@${(process.env.APP_URL ?? "localhost").replace(/^https?:\/\//, "")}>`;
53	  return {
54	    host,
55	    port: Number(s.smtp_port || process.env.SMTP_PORT || 587),
56	    user: s.smtp_user || process.env.SMTP_USER || "",
57	    pass: smtpPassPlain(s.smtp_pass) || process.env.SMTP_PASS || "",
58	    secure: (s.smtp_secure ?? process.env.SMTP_SECURE) === "true",
59	    from,
60	  };
61	}
62	
63	export async function mailConfigured(): Promise<boolean> {
64	  const c = await loadSmtp();
65	  return !!c.host || process.env.NXEON_LOCAL_MAIL === "1";
66	}
67	
68	function transport(c: Awaited<ReturnType<typeof loadSmtp>>) {
69	  if (!c.host) {
70	    // Local MTA fallback (Postfix/sendmail on the host)
71	    return nodemailer.createTransport({ sendmail: true, newline: "unix", path: "/usr/sbin/sendmail" });
72	  }
73	  // When the SMTP host is an internal IP (e.g. the mail VM at 10.20.0.10) but the
74	  // server presents a cert for its hostname (mail.nxeon.cloud), TLS validation
75	  // fails on an IP mismatch. `SMTP_TLS_SERVERNAME` lets us keep cert verification
76	  // on while telling TLS the name to validate against (and sets SNI accordingly).
77	  const servername = process.env.SMTP_TLS_SERVERNAME || undefined;
78	  return nodemailer.createTransport({
79	    host: c.host,
80	    port: c.port,
81	    secure: c.secure,
82	    auth: c.user ? { user: c.user, pass: c.pass } : undefined,
83	    ...(servername ? { tls: { servername } } : {}),
84	  });
85	}
