87	/** Template keys whose emails ship the itemised invoice as an attachment. */
88	const INVOICE_ATTACH_TEMPLATES = new Set(["receipt", "invoice_new", "renewal_reminder"]);
89	
90	export type MailAttachment = { filename: string; content: string | Buffer; contentType?: string };
91	
92	/**
93	 * Build the invoice attachment for an email. We now attach a REAL PDF, rendered
94	 * server-side by `lib/invoice-pdf.ts` (pdfkit — pure JS, no headless browser),
95	 * so accounting departments receive an actual `application/pdf` document rather
96	 * than the print-ready HTML that only became a PDF via the recipient's browser.
97	 * It carries the same branded layout and identifier as the on-site PDF download.
98	 */
99	async function invoiceAttachment(invoiceId: string): Promise<MailAttachment | null> {
100	  try {
101	    const invoice = await db.invoice.findUnique({
102	      where: { id: invoiceId },
103	      include: { user: { select: { name: true, email: true } } },
104	    });
105	    if (!invoice) return null;
106	    // Use the SAME branding the dashboard and the download route use, so the
107	    // invoice a customer receives by email carries the identifier they can quote
108	    // back at you — and the seller block, which only reaches emailed invoices
109	    // through this path. Previously this hardcoded `#00012`-style numbering while
110	    // every on-screen copy showed `INV-00012`: the customer and the support agent
111	    // would have been reading two different invoice numbers for one invoice.
112	    const branding = await invoiceBranding();
113	    const pdf = await renderInvoicePDF(invoice, invoice.user, branding);
114	    const filename = invoicePdfFilename(invoice.number, branding.numberPrefix);
115	    return { filename, content: pdf, contentType: "application/pdf" };
116	  } catch (e) {
117	    console.error("[mailer] failed to build invoice attachment:", e);
118	    return null;
119	  }
120	}
121	
122	export type SendMailOpts = {
123	  to: string;
124	  /** Optional Reply-To (e.g. route a contact-form reply straight to the sender). */
125	  replyTo?: string;
126	  /** Explicit subject. Optional when `template` is provided. */
127	  subject?: string;
128	  /** Explicit pre-rendered HTML. Optional when `template` is provided. */
129	  html?: string;
130	  text?: string;
131	  /** DB template key — when set (and no explicit `html`), the body is rendered via `renderTemplate`. */
132	  template?: string;
133	  /** Variables for `{{placeholders}}` when rendering from a template. */
134	  vars?: Record<string, unknown>;
135	  /** Attribution for the EmailLog row. */
136	  userId?: string | null;
137	  /** When set, attaches the invoice (auto for receipt/invoice_new/renewal_reminder templates). */
138	  invoiceId?: string;
139	  /** Extra attachments. */
140	  attachments?: MailAttachment[];
141	  /**
142	   * What KIND of message this is, for the notification-preference policy in
143	   * `lib/prefs.ts`. Supply it together with `userId` and this function enforces
144	   * the customer's choice centrally — see the gate below.
145	   *
146	   * Omitting it means "always send", which is the safe default: a message must
147	   * never be dropped because someone forgot to classify it.
148	   */
149	  kind?: NotifyKind;
150	  /**
151	   * When set, this is a MARKETING send and the message carries RFC 8058 one-click
152	   * unsubscribe headers pointing at this URL:
153	   *   List-Unsubscribe: <https://…/api/unsubscribe?token=…>
154	   *   List-Unsubscribe-Post: List-Unsubscribe=One-Click
155	   * Transactional sends never pass this, so they never get the headers. There is
156	   * no list-unsubscribe MAILBOX configured, so only the https one-click URL is
157	   * advertised (a mailto with no automation behind it would be worse than none).
158	   */
159	  listUnsubscribeUrl?: string;
160	};
161	
162	/** Matches an anchor's href attribute value (double-quoted, http/https only —
163	 *  every template composes links via `appUrl()`/`path()`, never a bare mailto
164	 *  or relative href, so this is the complete surface). */
165	const HREF_RE = /href="(https?:\/\/[^"]+)"/g;
166	
167	/**
168	 * Rewrite every trackable anchor in `html` to route through the click-redirect
169	 * endpoint, and append an invisible open-tracking pixel before `</body>`.
170	 *
171	 * An anchor is SKIPPED (left exactly as-is, not tracked) when its href carries
172	 * a bearer secret (password reset, email verification, invite tokens, …) —
173	 * see `containsSecretQueryParam`. The real destination for every rewritten
174	 * link is returned in `links`, positionally indexed to match the `/click/N`
175	 * URLs, for the caller to persist on the EmailLog row; a secret-bearing href
176	 * never enters that array, so it can never be re-served by the redirect route.
177	 */
178	function injectEmailTracking(html: string, emailLogId: string): { html: string; links: string[] } {
179	  const links: string[] = [];
180	  const base = appUrl();
181	  let out = html.replace(HREF_RE, (full, href: string) => {
182	    if (containsSecretQueryParam(href)) return full;
183	    const idx = links.length;
184	    links.push(href);
185	    return `href="${base}/api/track/email/${emailLogId}/click/${idx}"`;
186	  });
187	  const pixel = `<img src="${base}/api/track/email/${emailLogId}/open" width="1" height="1" alt="" style="display:block;border:0;outline:none;" />`;
188	  out = out.includes("</body>") ? out.replace("</body>", `${pixel}</body>`) : out + pixel;
189	  return { html: out, links };
190	}
191	
192	/**
193	 * Send an email. Never throws — logs and returns false on failure so callers
194	 * don't break flows. EVERY attempt is written to `EmailLog` (SENT on success,
195	 * FAILED + error otherwise) for the admin Logs viewer.
196	 *
197	 * NOTIFICATION PREFERENCES are enforced HERE, not at the call sites.
198	 * `User.notificationPrefs` was a column the customer edited and nothing read, so
199	 * turning off "email me about billing" changed nothing. Gating each send site
200	 * individually would have fixed today's sites and left every future one to
201	 * re-introduce the bug; gating centrally means a new send site inherits the
202	 * policy automatically and per-site checks become defence in depth.
203	 *
204	 * Two deliberate properties, both fail-open:
205	 *   - no `kind` (or no `userId`) → send. Unclassified is never silenced.
206	 *   - `mayDeliverTo` returns true for anything non-suppressible without touching
207	 *     the database, and also on a lookup error. A payment-failure or suspension
208	 *     warning must not be lost because a preference read failed.
209	 */
210	export async function sendMail(opts: SendMailOpts): Promise<boolean> {
211	  // Preference gate. CRITICAL kinds (payment failed, suspension, security
212	  // changes, data loss…) are declared non-suppressible in lib/prefs.ts and short
213	  // -circuit to true, so this costs nothing on the paths that matter most.
214	  if (opts.kind && opts.userId) {
215	    const allowed = await mayDeliverTo(opts.userId, opts.kind, "email");
216	    if (!allowed) {
217	      console.log(`[mail] suppressed ${opts.kind} to user ${opts.userId} by preference`);
218	      return false;
219	    }
220	  }
221	
222	  // Resolve subject/html: prefer explicit values, otherwise render the template.
223	  let subject = opts.subject ?? "";
224	  let html = opts.html ?? "";
225	  const templateKey = opts.template ?? null;
226	
227	  if (templateKey && !opts.html) {
228	    const rendered = await renderTemplate(templateKey, opts.vars ?? {});
229	    subject = opts.subject ?? rendered.subject;
230	    html = rendered.html;
231	  }
232	
233	  // Plain-text fallback derived from the UNTRACKED html — a text-only client
234	  // shows real URLs, not opaque tracking-redirect ones.
235	  const derivedText = opts.text ?? html.replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim();
236	
237	  // Open/click tracking: mint the EmailLog id up front so the pixel + rewritten
238	  // link URLs baked into the outgoing HTML reference a row that exists by the
239	  // time anyone opens or clicks. Applied uniformly to every send; see
240	  // injectEmailTracking's own doc comment for what's deliberately excluded.
241	  const emailLogId = randomUUID();
242	  const tracked = injectEmailTracking(html, emailLogId);
243	  html = tracked.html;
244	
245	  // Assemble attachments (invoice auto-attaches for the relevant templates).
246	  const attachments: MailAttachment[] = [...(opts.attachments ?? [])];
247	  const wantInvoice = opts.invoiceId && (!templateKey || INVOICE_ATTACH_TEMPLATES.has(templateKey));
248	  if (wantInvoice && opts.invoiceId) {
249	    const att = await invoiceAttachment(opts.invoiceId);
250	    if (att) attachments.push(att);
251	  }
252	
253	  try {
254	    const c = await loadSmtp();
255	    if (!c.host && process.env.NXEON_LOCAL_MAIL !== "1") {
256	      console.warn("[mailer] not configured — skipping email:", subject);
257	      await recordEmail(opts.to, subject, templateKey, html, "FAILED", "SMTP not configured", opts.userId, emailLogId, tracked.links);
258	      return false;
259	    }
260	    const t = transport(c);
261	    // RFC 8058 one-click unsubscribe — MARKETING sends only (a `listUnsubscribeUrl`
262	    // is passed). Transactional sends omit it and get no such headers.
263	    const listHeaders = opts.listUnsubscribeUrl
264	      ? {
265	          "List-Unsubscribe": `<${opts.listUnsubscribeUrl}>`,
266	          "List-Unsubscribe-Post": "List-Unsubscribe=One-Click",
267	        }
268	      : undefined;
269	    await t.sendMail({
270	      from: c.from,
271	      to: opts.to,
272	      replyTo: opts.replyTo || undefined,
273	      subject,
274	      html,
275	      text: derivedText,
276	      attachments: attachments.length ? attachments : undefined,
277	      ...(listHeaders ? { headers: listHeaders } : {}),
278	    });
279	    await recordEmail(opts.to, subject, templateKey, html, "SENT", null, opts.userId, emailLogId, tracked.links);
280	    return true;
281	  } catch (e) {
282	    console.error("[mailer] send failed:", e);
283	    await recordEmail(opts.to, subject, templateKey, html, "FAILED", String((e as Error)?.message ?? e), opts.userId, emailLogId, tracked.links);
284	    return false;
285	  }
286	}
