288	/**
289	 * Preferred path for DB-templated sends: render `key` with `vars`, send, log,
290	 * and (for billing templates) attach the invoice. Thin convenience over
291	 * `sendMail` for new callers.
292	 *
293	 * `kind` is forwarded to `sendMail`, which is the ONLY place the notification
294	 * policy is enforced. It used to be absent from this signature, so every send
295	 * routed through this wrapper was structurally incapable of honouring the
296	 * customer's "Account email" preference — a caller could not have opted in even
297	 * if it wanted to. That is the same class of defect as the column nothing read
298	 * (see `sendMail`), just one layer up: the gate exists, and the convenient path
299	 * quietly walks around it. Omitting `kind` still means "always send".
300	 */
301	export async function sendTemplate(
302	  key: string,
303	  to: string,
304	  vars: Record<string, unknown> = {},
305	  opts: {
306	    userId?: string | null;
307	    invoiceId?: string;
308	    attachments?: MailAttachment[];
309	    kind?: NotifyKind;
310	  } = {},
311	): Promise<boolean> {
312	  return sendMail({
313	    to,
314	    template: key,
315	    vars,
316	    userId: opts.userId,
317	    invoiceId: opts.invoiceId,
318	    attachments: opts.attachments,
319	    kind: opts.kind,
320	  });
321	}
