323	export async function sendTestMail(to: string): Promise<{ ok: boolean; error?: string }> {
324	  try {
325	    const c = await loadSmtp();
326	    const t = transport(c);
327	    const html = layout("SMTP test", "<p>Your Nxeon mail configuration works. 🎉</p>");
328	    await t.sendMail({ from: c.from, to, subject: "Nxeon SMTP test", html });
329	    await recordEmail(to, "Nxeon SMTP test", null, html, "SENT");
330	    return { ok: true };
331	  } catch (e: any) {
332	    return { ok: false, error: String(e?.message ?? e).slice(0, 300) };
333	  }
334	}
