336	const BRAND = { blue: "#3b82f6", purple: "#8a70fb", bg: "#0a101f", card: "#111a30" };
337	
338	/**
339	 * Shared responsive email shell (inline styles for client compatibility).
340	 * Kept for the synchronous, code-rendered `emails.*` templates below and any
341	 * existing importers. DB-template sends use `wrapEmail` in `lib/email-render`.
342	 */
343	export function layout(title: string, body: string): string {
344	  // Delegate to the shared premium shell so every email is consistent.
345	  const heading = title
346	    ? `<h1 style="margin:0 0 16px;font-size:21px;font-weight:700;color:#ffffff;line-height:1.25;">${title}</h1>`
347	    : "";
348	  return wrapEmail(`${heading}<div>${body}</div>`);
349	}
350	
351	export function button(href: string, label: string): string {
352	  return emailButton(href, label);
353	}
354	
355	// ---- Transactional templates ----
356	//
357	// The full transactional catalog lives in `lib/email-templates.ts` (30+
358	// templates, all composed from the shared inline-styled components). It is
359	// re-exported here as `emails` so every existing call site — `import { emails }
360	// from "@/lib/mailer"` — keeps working unchanged. Each entry returns
361	// `{ template, subject, html }`; the six original signatures are preserved.
362	export type { BuiltEmail };
363	
364	// ===========================================================================
365	// Card billing & dunning templates
366	//
367	// Renewals apply wallet credit first, then auto-charge the customer's saved
368	// card for the remainder. When that charge fails we retry on day 1, 3 and 5 and
369	// only suspend once the retries are exhausted. These templates carry that flow.
370	//
371	// They live here rather than in `lib/email-templates.ts` only because this file
372	// is the one owned by the card-billing change; they are built with the same
373	// `build()` shape and the same shared components, so they render identically to
374	// the rest of the catalog.
375	// ===========================================================================
376	
377	/**
378	 * Number of automatic retries in the dunning sequence (day 1, day 3, day 5).
379	 * `paymentRetryFailed` uses it to tell the customer how many attempts are left,
380	 * so the worker's retry schedule and this copy must agree.
381	 */
382	export const DUNNING_RETRY_ATTEMPTS = 3;
383	
384	/**
385	 * Same composition helper as `lib/email-templates.ts` (which keeps its copy
386	 * module-private): eyebrow → heading → body blocks → single CTA → optional
387	 * footnote, wrapped with a preheader by the shared shell.
388	 */
389	function build(opts: {
390	  template: string;
391	  subject: string;
392	  preheader: string;
393	  eyebrow?: string;
394	  accent?: Accent;
395	  heading: string;
396	  blocks: string[];
397	  cta?: { href: string; label: string; accent?: Accent };
398	  note?: string;
399	}): BuiltEmail {
400	  const parts: string[] = [];
401	  if (opts.eyebrow) parts.push(emailEyebrow(opts.eyebrow, opts.accent ?? "violet"));
402	  parts.push(emailHeading(opts.heading));
403	  parts.push(...opts.blocks);
404	  if (opts.cta) parts.push(emailButton(opts.cta.href, opts.cta.label, opts.cta.accent ?? "violet"));
405	  if (opts.note) parts.push(emailNote(opts.note));
406	  return {
407	    template: opts.template,
408	    subject: opts.subject,
409	    html: wrapEmail(parts.join("\n"), { preheader: opts.preheader }),
410	  };
411	}
412	
413	/** Masked card display used wherever we echo the saved card back. */
414	const cardLabel = (last4: string) => `&bull;&bull;&bull;&bull;&nbsp;${last4}`;
415	
416	/** `MM/YYYY` from the raw Stripe expiry fields — never guessed, only formatted. */
417	const expiryLabel = (expMonth: number, expYear: number) => `${String(expMonth).padStart(2, "0")}/${expYear}`;
418	
419	/** Reassurance line reused across the dunning sequence. Nothing is suspended yet. */
420	const stillRunning = (hostname: string, extra = "") =>
421	  emailBanner(`<b>${hostname}</b> is still running. Nothing has been suspended.${extra ? ` ${extra}` : ""}`, "success");
422	
423	const legacyPaymentFailed = catalogEmails.paymentFailed;
424	type LegacyPaymentFailedArgs = Parameters<typeof legacyPaymentFailed>[0];
425	
426	/**
427	 * Card charge declined — FIRST failure of the dunning sequence.
428	 *
429	 * Overloaded so the original catalog shape (`{ amount, reason, updateUrl? }`,
430	 * still used by the admin template previewer) keeps working alongside the new
431	 * renewal-dunning shape.
432	 */
433	function paymentFailed(a: LegacyPaymentFailedArgs): BuiltEmail;
434	function paymentFailed(
435	  hostname: string,
436	  amountFormatted: string,
437	  last4: string,
438	  retryDateFormatted: string,
439	  billingUrl: string,
440	): BuiltEmail;
441	function paymentFailed(
442	  a: string | LegacyPaymentFailedArgs,
443	  amountFormatted?: string,
444	  last4?: string,
445	  retryDateFormatted?: string,
446	  billingUrl?: string,
447	): BuiltEmail {
448	  if (typeof a !== "string") return legacyPaymentFailed(a);
449	  const hostname = a;
450	  const amount = amountFormatted ?? "";
451	  const card = last4 ?? "";
452	  const retryDate = retryDateFormatted ?? "";
453	  const href = billingUrl ?? `${appUrl()}/dashboard/billing`;
454	  return build({
455	    template: "payment_failed",
456	    subject: `Card declined for ${hostname} — we'll retry ${retryDate}`,
457	    preheader: `${hostname} is still running. We'll try the card again on ${retryDate}.`,
458	    eyebrow: "Payment issue",
459	    accent: "warn",
460	    heading: "We couldn't charge your card",
461	    blocks: [
462	      emailParagraph(
463	        `The renewal payment for <b>${hostname}</b> didn't go through. Declines are usually something on the bank's side — a routine fraud check, a spending limit, or a card that's been reissued — so this often isn't anything you did.`,
464	      ),
465	      stillRunning(hostname),
466	      emailPanel(
467	        emailKeyValue([
468	          ["Server", hostname],
469	          ["Amount due", amount],
470	          ["Card", cardLabel(card)],
471	          ["Next attempt", retryDate],
472	        ]),
473	        "warn",
474	      ),
475	      emailParagraph(
476	        `We'll try the same card again on <b>${retryDate}</b>. If you'd rather not wait, update your card and we'll charge it straight away.`,
477	      ),
478	    ],
479	    cta: { href, label: "Update payment method", accent: "warn" },
480	    note: "If your bank asked you to approve the charge, approving it is enough. Anything else — just reply to this email and our team will take a look.",
481	  });
482	}
483	
484	const billingEmails = {
485	  /** Successful auto-charge against the saved card. */
486	  paymentReceipt: (amountFormatted: string, description: string, last4: string): BuiltEmail =>
487	    build({
488	      template: "payment_receipt",
489	      subject: `Receipt for ${amountFormatted} — card ending ${last4}`,
490	      preheader: `We charged ${amountFormatted} to your saved card. Everything is running as normal.`,
491	      eyebrow: "Receipt",
492	      accent: "success",
493	      heading: "Payment received",
494	      blocks: [
495	        emailParagraph(
496	          "Your renewal has been paid automatically using the card saved on your account. Everything is running as normal — there's nothing you need to do.",
497	        ),
498	        emailPanel(
499	          emailKeyValue([
500	            ["Amount", `<span style="color:#15a34a;">${amountFormatted}</span>`],
501	            ["For", description],
502	            ["Card", cardLabel(last4)],
503	          ]),
504	          "success",
505	        ),
506	        emailParagraph("Any wallet credit on your account was applied first; the amount above is what we charged to the card."),
507	      ],
508	      cta: { href: `${appUrl()}/dashboard/invoices`, label: "View invoices" },
509	      note: "Keep this email for your records, or download the itemised invoice from your dashboard at any time.",
510	    }),
511	
512	  /** First declined charge in the dunning sequence (see the overloads above). */
513	  paymentFailed,
514	
515	  /** A later retry in the dunning sequence was declined. */
516	  paymentRetryFailed: (
517	    hostname: string,
518	    amountFormatted: string,
519	    attempt: number,
520	    finalDateFormatted: string,
521	    billingUrl: string,
522	  ): BuiltEmail => {
523	    const remaining = Math.max(0, DUNNING_RETRY_ATTEMPTS - attempt);
524	    const remainingLine =
525	      remaining > 0
526	        ? `We'll try ${remaining} more time${remaining === 1 ? "" : "s"} before then.`
527	        : "That was the last automatic attempt.";
528	    return build({
