export async function recordEmail(
  toEmail: string,
  subject: string,
  template: string | null,
  html: string,
  status: "SENT" | "FAILED",
  error?: string | null,
  userId?: string | null,
  /** Pre-generated id (lib/mailer.ts mints one so click/open tracking URLs can
   *  reference the row before it exists). Falls back to Prisma's own cuid(). */
  id?: string,
  /** Real destination URLs, positionally indexed — see the EmailLog.links doc
   *  comment in prisma/schema.prisma. Already excludes any secret-bearing href. */
  links?: string[] | null,
): Promise<void> {
  try {
    await (await prisma()).emailLog.create({
      data: {
        ...(id ? { id } : {}),
        toEmail,
        subject: subject.slice(0, 500),
        template: template ?? null,
        html: redactEmailSecrets(html),
        status,
        error: error ? String(error).slice(0, 1000) : null,
        userId: userId ?? null,
        links: links && links.length ? links : undefined,
      },
    });
  } catch (e) {
    console.error("[email-render] failed to record EmailLog:", e);
  }
  await pruneEmailLog(Date.now());
