/**
 * Critical transactional email retry — pure eligibility logic.
 *
 * `lib/mailer.ts`'s `sendMail()` accepts a `kind` (`NotifyKind`, see
 * `lib/prefs.ts`) that marks certain messages CRITICAL for delivery-preference
 * purposes: a customer's notification settings can never suppress them
 * (payment failures, suspensions, security changes, the "your server is
 * ready" deploy confirmation, ...). That classification was never persisted
 * anywhere retryable — `EmailLog` recorded `status`/`error` but not `kind` —
 * so a one-off transient SMTP failure on one of these (e.g. the Mailcow
 * "454 4.7.0 Temporary authentication failure" hiccup that prompted this) just
 * silently dropped the message. No retry, no signal, customer never notified.
 *
 * `worker/critical-email-retry.ts` now persists `kind` on every `EmailLog` row
 * (see `sendMail`/`recordEmail`) and runs a bounded sweep that finds FAILED
 * rows whose `kind` is CRITICAL, within a recency window, under a retry cap,
 * and re-sends the ALREADY-RENDERED `html`/`subject`/`to` — simpler and safer
 * than re-deriving the original template context from scratch.
 *
 * This module holds the pure "which rows qualify" predicate (and the shared
 * constants) so that decision is unit-testable without a database. All the
 * actual I/O — querying, sending, updating rows — lives in the worker module.
 */

import { NOTIFY_KINDS } from "./prefs";

/**
 * Every `NotifyKind` whose tier is CRITICAL, derived from `lib/prefs.ts`'s
 * `NOTIFY_KINDS` — the single source of truth for the delivery policy — so
 * this set can never drift from what "critical" actually means there.
 */
export const CRITICAL_RETRY_KINDS: ReadonlySet<string> = new Set(
  Object.entries(NOTIFY_KINDS)
    .filter(([, tier]) => tier === "CRITICAL")
    .map(([kind]) => kind),
);

/** Don't retry something stale — a send this old is long past being timely. */
export const RETRY_WINDOW_HOURS = 48;

/** Bounded per-row retry cap. Never infinite. */
export const MAX_RETRIES_PER_EMAIL = 3;

/** Bounded per-sweep-run budget — a backlog can't hammer the mail relay. */
export const MAX_RETRIES_PER_SWEEP = 20;

/** The subset of `EmailLog` fields the eligibility check actually needs. */
export type RetryCandidateRow = {
  status: string;
  kind: string | null;
  createdAt: Date;
  retryCount: number;
};

/**
 * Does this `EmailLog` row qualify for an automatic retry right now?
 *
 * Pure and deterministic given `now` — no I/O, no clock reads other than the
 * one passed in. Checks, in order:
 *   1. `status` is `"FAILED"` — a `"SENT"` row already succeeded.
 *   2. `kind` is set AND is one of the CRITICAL kinds — this sweep only ever
 *      touches messages a customer preference could never legitimately drop.
 *   3. `retryCount` is under the cap — bounded, never retried forever.
 *   4. `createdAt` is within the recency window (and not in the future,
 *      which would only happen from clock skew — treated as ineligible
 *      rather than trusted).
 */
export function isRetryEligible(
  row: RetryCandidateRow,
  now: Date = new Date(),
  opts: { windowHours?: number; maxRetries?: number } = {},
): boolean {
  if (row.status !== "FAILED") return false;
  if (!row.kind || !CRITICAL_RETRY_KINDS.has(row.kind)) return false;

  const maxRetries = opts.maxRetries ?? MAX_RETRIES_PER_EMAIL;
  if (row.retryCount >= maxRetries) return false;

  const windowMs = (opts.windowHours ?? RETRY_WINDOW_HOURS) * 3600_000;
  const ageMs = now.getTime() - row.createdAt.getTime();
  if (ageMs < 0) return false; // future timestamp — clock skew, never trust it
  if (ageMs > windowMs) return false;

  return true;
}

