// Critical transactional email retry sweep (worker task).
//
// Registered on the worker loop (worker/index.ts). Gated behind the
// `critical_email_retry_enabled` Setting (default TRUE — see the master
// kill-switch below), matching the pattern in worker/marketing.ts's
// marketingDiscoverySweep: a single flag an operator can flip off without a
// deploy, defaulting ON because retrying a message that was always going to be
// sent anyway is low-risk.
//
// WHY THIS EXISTS: `sendMail()` (lib/mailer.ts) marks certain `NotifyKind`s
// CRITICAL (lib/prefs.ts) — payment failures, suspensions, security changes,
// the "your server is ready" deploy confirmation, ... — meaning a customer's
// notification preferences can never suppress them. A real "server ready"
// send once failed on a transient Mailcow auth hiccup and just silently
// dropped, with no retry and no signal that the customer never got notified.
// This sweep closes that gap: it finds FAILED `EmailLog` rows whose `kind` is
// CRITICAL, within a bounded recency window, under a bounded retry cap (see
// lib/critical-email-retry.ts for the pure eligibility check), and re-sends
// the ALREADY-RENDERED `html`/`subject`/`to` straight through `sendMail()` —
// simpler and safer than re-deriving the original template context (server /
// user objects, etc.) from scratch.
//
// The resend itself writes its OWN new EmailLog row, like any other send —
// but deliberately WITHOUT `kind` set (see the loop below), so that new row
// can never itself become a fresh retry root. The ORIGINAL row's
// `retryCount` is what actually bounds an unlucky message to
// MAX_RETRIES_PER_EMAIL attempts total, not a chain of resend rows each
// starting a fresh counter at 0.
//
// Polled every 10–15 min (see worker/index.ts) — catching a transient blip
// doesn't need to be aggressive, and the sweep paces its own sends.

import { db } from "../lib/db";
import { getSettingBool } from "../lib/settings";
import { sendMail } from "../lib/mailer";
import {
  isRetryEligible,
  CRITICAL_RETRY_KINDS,
  RETRY_WINDOW_HOURS,
  MAX_RETRIES_PER_EMAIL,
  MAX_RETRIES_PER_SWEEP,
} from "../lib/critical-email-retry";

/** Gentle pacing between resends so a backlog never bursts the SMTP relay. */
const SEND_GAP_MS = 1000;
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

export async function criticalEmailRetrySweep(): Promise<void> {
  // ===== MASTER KILL-SWITCH (first line) =====
  // Default TRUE: unlike a new outbound campaign, this only ever retries a
  // message that was already supposed to go out. An operator who wants it off
  // (e.g. mid SMTP-provider incident, to stop hammering a relay that's already
  // down) flips `critical_email_retry_enabled` to false.
  if (!(await getSettingBool("critical_email_retry_enabled", true))) return;

  const now = new Date();
  const cutoff = new Date(now.getTime() - RETRY_WINDOW_HOURS * 3600_000);

  // Over-fetch a little past the sweep budget so the in-process eligibility
  // check (defence in depth against the query above) still has enough rows to
  // fill the budget even if a few are filtered out.
  const rows = await db.emailLog
    .findMany({
      where: {
        status: "FAILED",
        kind: { in: Array.from(CRITICAL_RETRY_KINDS) },
        createdAt: { gte: cutoff },
        retryCount: { lt: MAX_RETRIES_PER_EMAIL },
      },
      orderBy: { createdAt: "asc" },
      take: MAX_RETRIES_PER_SWEEP * 3,
    })
    // `kind`/`retryCount` not present yet (schema not migrated on this
    // environment) — no-op, mirrors the other sweeps' .catch(() => null) guard.
    .catch(() => null);
  if (!rows || rows.length === 0) return;

  let attempted = 0;
  let recovered = 0;
  let stillFailing = 0;

  for (const row of rows) {
    if (attempted >= MAX_RETRIES_PER_SWEEP) break;
    if (!isRetryEligible(row, now)) continue;
    attempted++;

    try {
      const ok = await sendMail({
        to: row.toEmail,
        subject: row.subject,
        html: row.html,
        userId: row.userId,
        // Deliberately NOT forwarding `row.kind` here — see the file-level doc
        // comment. Delivery is unaffected: `row.kind` is CRITICAL by
        // construction of the query above, and `mayDeliverTo` always allows
        // CRITICAL kinds through regardless of `kind` being passed. Omitting
        // it only changes what gets written to THIS resend's own EmailLog row.
      });
      await db.emailLog.update({
        where: { id: row.id },
        data: ok
          ? { status: "SENT", error: null, retryCount: { increment: 1 } }
          : { retryCount: { increment: 1 } },
      });
      if (ok) recovered++;
      else stillFailing++;
    } catch (e) {
      stillFailing++;
      try {
        await db.emailLog.update({ where: { id: row.id }, data: { retryCount: { increment: 1 } } });
      } catch {
        // best-effort — a failed counter bump just means this row gets tried
        // again next sweep, which is safe (still bounded by the window).
      }
      console.error(`[critical-email-retry] resend failed for EmailLog ${row.id}:`, e);
    }

    await sleep(SEND_GAP_MS);
  }

  if (attempted > 0) {
    console.log(
      `[critical-email-retry] sweep: ${attempted} attempted, ${recovered} recovered, ${stillFailing} still failing`,
    );
  }
}

