import { test } from "node:test";
import assert from "node:assert/strict";
import {
  isRetryEligible,
  CRITICAL_RETRY_KINDS,
  RETRY_WINDOW_HOURS,
  MAX_RETRIES_PER_EMAIL,
  type RetryCandidateRow,
} from "../lib/critical-email-retry.ts";
import { NOTIFY_KINDS } from "../lib/prefs.ts";

const NOW = new Date("2026-08-26T12:00:00.000Z");
const hoursAgo = (h: number) => new Date(NOW.getTime() - h * 3600_000);

const baseRow = (overrides: Partial<RetryCandidateRow> = {}): RetryCandidateRow => ({
  status: "FAILED",
  kind: "provision_ready",
  createdAt: hoursAgo(1),
  retryCount: 0,
  ...overrides,
});

test("CRITICAL_RETRY_KINDS is derived from prefs.ts and contains the expected kinds", () => {
  // Sanity: every kind this module treats as retryable really is tier CRITICAL
  // in the single source of truth, and nothing CRITICAL there is missing here.
  const criticalInPrefs = Object.entries(NOTIFY_KINDS)
    .filter(([, tier]) => tier === "CRITICAL")
    .map(([kind]) => kind)
    .sort();
  assert.deepEqual([...CRITICAL_RETRY_KINDS].sort(), criticalInPrefs);
  assert.ok(CRITICAL_RETRY_KINDS.has("provision_ready"));
  assert.ok(CRITICAL_RETRY_KINDS.has("payment_failed"));
  assert.ok(CRITICAL_RETRY_KINDS.has("suspension"));
  // An ACCOUNT-tier kind must NOT be treated as retryable by this sweep.
  assert.equal(CRITICAL_RETRY_KINDS.has("receipt"), false);
  assert.equal(CRITICAL_RETRY_KINDS.has("welcome"), false);
  // PRODUCT-tier (marketing) must never be retried by this sweep either.
  assert.equal(CRITICAL_RETRY_KINDS.has("product_news"), false);
});

test("eligible: a recent FAILED critical-kind row under the retry cap", () => {
  assert.equal(isRetryEligible(baseRow(), NOW), true);
});

test("ineligible: status is SENT, not FAILED", () => {
  assert.equal(isRetryEligible(baseRow({ status: "SENT" }), NOW), false);
});

test("ineligible: kind is null (never classified)", () => {
  assert.equal(isRetryEligible(baseRow({ kind: null }), NOW), false);
});

test("ineligible: kind is set but not a CRITICAL tier", () => {
  assert.equal(isRetryEligible(baseRow({ kind: "receipt" }), NOW), false);
  assert.equal(isRetryEligible(baseRow({ kind: "product_news" }), NOW), false);
});

test("ineligible: an unrecognised/typo'd kind string is NOT treated as retryable", () => {
  // Note this differs from notifyTier()'s fail-CRITICAL default in prefs.ts —
  // here an unrecognised string simply isn't in the known-critical set, so the
  // retry sweep skips it rather than guessing. Delivery itself is unaffected
  // (sendMail/mayDeliverTo still defaults an unknown kind to non-suppressible);
  // this sweep just declines to auto-retry something it doesn't recognise.
  assert.equal(isRetryEligible(baseRow({ kind: "not_a_real_kind" }), NOW), false);
});

test("ineligible: retryCount has reached the cap", () => {
  assert.equal(isRetryEligible(baseRow({ retryCount: MAX_RETRIES_PER_EMAIL }), NOW), false);
  assert.equal(isRetryEligible(baseRow({ retryCount: MAX_RETRIES_PER_EMAIL + 1 }), NOW), false);
});

test("eligible: retryCount one below the cap", () => {
  assert.equal(isRetryEligible(baseRow({ retryCount: MAX_RETRIES_PER_EMAIL - 1 }), NOW), true);
});

test("ineligible: older than the recency window", () => {
  assert.equal(isRetryEligible(baseRow({ createdAt: hoursAgo(RETRY_WINDOW_HOURS + 1) }), NOW), false);
});

test("eligible: right at the edge, just inside the recency window", () => {
  assert.equal(isRetryEligible(baseRow({ createdAt: hoursAgo(RETRY_WINDOW_HOURS - 0.01) }), NOW), true);
});

test("ineligible: a future createdAt (clock skew) is never trusted", () => {
  const future = new Date(NOW.getTime() + 3600_000);
  assert.equal(isRetryEligible(baseRow({ createdAt: future }), NOW), false);
});

test("custom windowHours/maxRetries options are honoured", () => {
  const row = baseRow({ createdAt: hoursAgo(2), retryCount: 1 });
  assert.equal(isRetryEligible(row, NOW, { windowHours: 1 }), false);
  assert.equal(isRetryEligible(row, NOW, { windowHours: 3 }), true);
  assert.equal(isRetryEligible(row, NOW, { maxRetries: 1 }), false);
  assert.equal(isRetryEligible(row, NOW, { maxRetries: 2 }), true);
});

